 'delete-record':b=>confirmAction('Excluir registro?','Esta ação remove o registro. Excluir uma sessão pode alterar a ofensiva.',async()=>{await remove(b.dataset.id);await refreshStats();toast('Registro excluído.')},'Excluir'),
 'rest':()=>{if(state.draft.data.paused_at)return;state.draft.data.rest_until=Date.now()+90000;changed();updateTimes()},'skip-rest':()=>{state.draft.data.rest_until=null;changed();updateTimes()},
 'set-done':b=>{if(state.draft.data.paused_at)throw new Error('Retome o treino antes de registrar séries.');const e=state.draft.data.exercises[Number(b.dataset.ex)],s=e.sets[Number(b.dataset.set)];if(!(s.reps>0&&s.reps<=200&&s.kg>=0&&s.kg<=1000))throw new Error('Informe carga e repetições válidas antes de concluir.');s.done=!s.done;if(s.done)state.draft.data.rest_until=Date.now()+(e.rest||90)*1000;changed();render()},
 'speak-ex':b=>{const e=state.draft.data.exercises[Number(b.dataset.ex)];speak(e.name+'. '+e.purpose+'. '+e.execution)},
 'edit-session':()=>routineEditor(state.draft,true),
 'leave-session':async()=>{await saveDraft();state.route='today';render()},
 'discard-session':()=>confirmAction('Descartar sessão?','As séries desta sessão serão removidas. Sua ficha original permanece.',async()=>{clearTimeout(saveTimer);if(savePromise)await savePromise;if(state.records.some(r=>r.id===state.draft.id))await remove(state.draft.id);state.draft=null;state.dirty=false;localStorage.removeItem('forma-draft-'+state.user.id);if(state.demo)demoPersist();toast('Sessão descartada.')},'Descartar'),
 'finish':()=>{const n=completed(state.draft.data);confirmAction('Finalizar treino?',`${n} exercícios completos. ${n>=3?'Este treino atende ao mínimo da ofensiva.':'A sessão será registrada, mas não contará para a ofensiva.'}`,async()=>{clearTimeout(saveTimer);await saveDraft();const d=clone(state.draft.data);d.duration_s=activeSeconds(d);await put('workout',d,d.log_id);await remove(state.draft.id);state.draft=null;state.dirty=false;localStorage.removeItem('forma-draft-'+state.user.id);await refreshStats();if(state.demo)demoPersist();toast(n>=3?'Treino concluído. Mais um dia de constância!':'Sessão registrada. Respeite seu ritmo.');},'Finalizar')},
 'review-workout':b=>{const r=state.records.find(r=>r.id===b.dataset.id);formModal('Revisar sessão',`<p class="muted">A data de conclusão é preservada. Alterar séries recalcula a ofensiva.</p>${r.data.exercises.map((e,i)=>`<div class="list-editor"><h3>${esc(e.name)}</h3>${e.sets.map((s,j)=>`<div class="set-row"><span>${j+1}</span><input type="number" name="kg_${i}_${j}" value="${s.kg}" min="0" max="1000" step="0.5" aria-label="Carga"><input type="number" name="reps_${i}_${j}" value="${s.reps}" min="1" max="200" aria-label="Repetições"><input type="checkbox" name="done_${i}_${j}" ${s.done?'checked':''} aria-label="Série concluída"></div>`).join('')}</div>`).join('')}`,async f=>{const d=clone(r.data);d.exercises.forEach((e,i)=>e.sets.forEach((s,j)=>{s.kg=Number(f[`kg_${i}_${j}`]);s.reps=Number(f[`reps_${i}_${j}`]);s.done=f[`done_${i}_${j}`]==='on'}));await put('workout',d,r.id,r.version);await refreshStats();toast('Sessão atualizada.')});},
 'recover-draft':()=>{const c=JSON.parse(localStorage.getItem('forma-draft-'+state.user.id)||'null');if(!c?.dirty)throw new Error('Não há rascunho pendente.');formModal('Resolver rascunho',`<p>Você pode carregar a versão atual da nuvem ou aplicar seu rascunho local sobre ela. Revise antes de substituir alterações de outro aparelho.</p><label>Versão<select name="choice"><option value="cloud">Usar versão da nuvem</option><option value="local">Aplicar meu rascunho local</option></select></label>`,async f=>{const rows=await api('records'),cloud=rows.find(r=>r.kind==='draft');state.records=rows;if(f.choice==='local'){if(cloud&&cloud.id!==c.draft.id)throw new Error('A nuvem possui outra sessão. Finalize ou descarte antes de aplicar este rascunho.');state.draft={...c.draft,version:cloud?.version};state.dirty=true;await saveDraft()}else{state.draft=cloud||null;state.dirty=false;localStorage.removeItem('forma-draft-'+state.user.id);state.sync='Salvo na nuvem'}toast('Versão escolhida.');});},
 'refresh-friends':async()=>{if(state.demo)throw new Error('Amizades reais precisam do Supabase.');state.friends=await api('friends');render()},
 'add-friend':async b=>{await api('friends','POST',{target:b.dataset.id});state.friends=await api('friends');render();toast('Convite enviado.')},
